CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,content TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS lab_content (id SERIAL PRIMARY KEY,content_key TEXT NOT NULL UNIQUE,page TEXT NOT NULL CHECK (page IN ('home','about')),area TEXT NOT NULL CHECK (area IN ('intro','scope','card','note')),title TEXT DEFAULT '',title_en TEXT DEFAULT '',content TEXT NOT NULL,content_en TEXT NOT NULL,icon TEXT DEFAULT 'none' CHECK (icon IN ('document','phone','focus','none')),sort_order INTEGER DEFAULT 10,published INTEGER DEFAULT 1 CHECK (published IN (0,1)),image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());